<?php $id=\Chengyu\Core\Input::integer($_GET['id']??0);$page=\Chengyu\Core\Input::integer($_GET['page']??1,1,100000);partial('platform_header',['title'=>$title,'kicker'=>'LISTEN / RESPOND','symbol'=>'message','subtitle'=>'A private support inbox with safe reusable replies and explicit status changes.']); ?>
<div class="section"><?php if($id): partial('support_thread',['ticket'=>$a->support->ticket($me,$id),'supportPage'=>$page]);else: $state=\Chengyu\Core\Input::text($_GET['state']??'',20);$tickets=$a->support->listing($me,$page,$state); ?>
<div class="row wrap filters section"><?php foreach(array_merge([''],\Chengyu\Services\SupportDesk::STATES) as $stateItem): ?><a class="filter <?= $stateItem===$state?'active':'' ?>" href="<?= e(au('support',['state'=>$stateItem])) ?>"><?= t($stateItem?:'All') ?></a><?php endforeach ?></div>
<div class="platform-grid"><section class="panel commerce-panel"><h2><?= t('Customer tickets') ?> <span class="pill"><?= (int)$tickets['total'] ?></span></h2><?php foreach($tickets['items'] as $entry): ?><a class="platform-list-link" href="<?= e(au('support',['id'=>$entry['id']])) ?>"><span><strong><?= e($entry['subject']) ?></strong><small><?= e($entry['display_name']) ?></small></span><small><?= t($entry['status']) ?> / <?= t($entry['priority']) ?></small></a><?php endforeach ?><?php if(!$tickets['items']){empty_state('No support tickets yet.','message');}partial('pagination',['feed'=>$tickets,'tab'=>'support']); ?></section>
<aside class="panel commerce-panel"><h2><?= t('Reply templates') ?></h2><?php $edit=\Chengyu\Core\Input::integer($_GET['template']??0);$template=$edit?$a->db->one('SELECT * FROM cy_support_templates WHERE id=?',[$edit]):null;if($edit&&!$template){throw new \Chengyu\Core\Problem('Reply template not found.',404);} ?>
<?= form_start('support_template','','',false).hidden('id',$edit).hidden('revision',$template['revision']??0) ?><?php field('title','Template name',$template['title']??'','text',['required'=>'required','maxlength'=>'100']);field('body','Reply text',$template['body']??'','textarea',['required'=>'required','maxlength'=>'4000']);check_field('active','Enabled',$template?(bool)$template['active']:true);button('Save template','secondary','check'); ?></form>
<?php foreach($a->db->all('SELECT id,title,active FROM cy_support_templates ORDER BY id DESC LIMIT 100') as $row): ?><a class="platform-list-link" href="<?= e(au('support',['template'=>$row['id']])) ?>"><span><?= e($row['title']) ?></span><small><?= t($row['active']?'Enabled':'Disabled') ?></small></a><?php endforeach ?></aside></div><?php endif ?></div>
